#include "discover.h"
#include "parse_evd.h"
#include <dirent.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    char name[128];
    char relpath[256];
} prior_row;

static int name_seen(const char *name, const prior_row *rows, int n) {
    for (int i = 0; i < n; i++)
        if (strcmp(rows[i].name, name) == 0) return 1;
    return 0;
}

static int load_prior(prior_row *rows, int cap) {
    FILE *f = fopen("/app/rivetbay/intake/current.ledger", "r");
    if (!f) return 0;
    int n = 0;
    char line[1024];
    while (n < cap && fgets(line, sizeof(line), f)) {
        char *p1 = strchr(line, '|');
        if (!p1) continue;
        *p1++ = 0;
        char *p2 = strchr(p1, '|');
        if (!p2) continue;
        *p2 = 0;
        if (!line[0] || !p1[0]) continue;
        snprintf(rows[n].name, sizeof(rows[n].name), "%s", line);
        snprintf(rows[n].relpath, sizeof(rows[n].relpath), "%s", p1);
        n++;
    }
    fclose(f);
    return n;
}

static int emit_row(FILE *out, const char *relpath) {
    char path[512], name[128], fields[512];
    snprintf(path, sizeof(path), "/app/rivetbay/%s", relpath);
    if (parse_evd_file(path, name, fields, sizeof(fields)) != 0) return 0;
    fprintf(out, "%s|%s|%s\n", name, relpath, fields);
    return 1;
}

void discover_all(void) {
    prior_row prior[256];
    char pending[256][256];
    int nprior = load_prior(prior, 256), npend = 0;
    DIR *d = opendir("/app/rivetbay/evd");
    if (!d) return;

    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        size_t len = strlen(ent->d_name);
        if (len < 5 || strcmp(ent->d_name + len - 4, ".evd") != 0) continue;
        char path[512], name[128], fields[512];
        snprintf(path, sizeof(path), "/app/rivetbay/evd/%s", ent->d_name);
        if (parse_evd_file(path, name, fields, sizeof(fields)) != 0) continue;
        if (name_seen(name, prior, nprior)) continue;
        int duplicate = 0;
        for (int i = 0; i < npend; i++) {
            char other_path[512], other_name[128];
            snprintf(other_path, sizeof(other_path), "/app/rivetbay/%s", pending[i]);
            if (parse_evd_file(other_path, other_name, fields, sizeof(fields)) == 0 &&
                strcmp(name, other_name) == 0) duplicate = 1;
        }
        if (!duplicate && npend < 256) {
            snprintf(pending[npend], sizeof(pending[npend]), "evd/%s", ent->d_name);
            npend++;
        }
    }
    closedir(d);

    FILE *out = fopen("/app/rivetbay/intake/current.ledger.tmp", "w");
    if (!out) return;
    for (int i = 0; i < nprior; i++) emit_row(out, prior[i].relpath);
    for (int i = 0; i < npend; i++) emit_row(out, pending[i]);
    if (fclose(out) != 0 || rename("/app/rivetbay/intake/current.ledger.tmp",
                                   "/app/rivetbay/intake/current.ledger") != 0)
        remove("/app/rivetbay/intake/current.ledger.tmp");
}
EOF
